const payload = $json.body ?? $json;
const toolCall = payload.message?.toolCallList?.[0] ?? payload.message?.toolCalls?.[0] ?? payload.toolCall ?? null;
const wrappedToolCall = payload.message?.toolWithToolCallList?.[0]?.toolCall ?? null;
const rawArgs = toolCall?.parameters ?? toolCall?.arguments ?? wrappedToolCall?.function?.parameters ?? wrappedToolCall?.function?.arguments ?? toolCall?.function?.arguments ?? payload.arguments ?? payload;
const args = typeof rawArgs === 'string' ? JSON.parse(rawArgs) : rawArgs;
const normalizeName = (value) => (value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
const normalizePhone = (value) => {
  if (!value) return null;
  const digits = String(value).replace(/\D/g, '');
  if (!digits) return null;
  if (digits.startsWith('00') && digits.length > 2) return `+${digits.slice(2)}`;
  if (digits.length === 9) return `+48${digits}`;
  if (digits.length === 11 && digits.startsWith('48')) return `+${digits}`;
  if (String(value).trim().startsWith('+')) return `+${digits}`;
  return digits.length >= 8 ? `+${digits}` : null;
};
const fullName = args.fullName || null;
const phoneE164 = args.phoneE164 || normalizePhone(args.phoneRaw) || null;
const details = [];
if (!fullName && !phoneE164 && !args.phoneRaw) details.push('fullName or phoneE164 or phoneRaw is required');
return [{ json: {
  ok: details.length === 0,
  toolCallId: toolCall?.id || wrappedToolCall?.id || payload.toolCallId || null,
  requestId: args.requestId || payload.requestId || null,
  fullName,
  normalizedFullName: normalizeName(fullName),
  phoneE164,
  validationErrors: details
} }];

